INSERT OR REPLACE INTO tbts (id, doc_code, title, doc_owner, last_revision, next_revision, category, prepare_text, reason_text, why_text, outline_text, content_json, comprehension_question, comprehension_options_json, correct_option_index, active) VALUES ('AVC032', 'AVC032', 'Safe Use of Step Ladder', 'Operations Director', '05/01/2026', '04/01/2028', 'Working at Height', 'Quiet location? No distractions? Talk aids ready?', 'To ensure operatives understand the risk of working at height and are safely working with step ladders.', 'To prevent injuries from falls from step ladder', 'This TBT covers the safe use of step ladders.', '{"prepare": "Quiet location? No distractions? Talk aids ready?", "reason": "To ensure operatives understand the risk of working at height and are safely working with step ladders.", "why": "To prevent injuries from falls from step ladder", "outline": "This TBT covers the safe use of step ladders.", "sections": [{"title": "1. Introduction", "body": "Falls from height are still one of the biggest causes of death and injury in the UK workplace. Many of these accidents are due to the inappropriate use of ladders and stepladders because their simple design and ease of use and familiarity, it is possible that the safety implications of their use are overlooked."}, {"title": "2. Responsibilities", "subsections": [{"heading": "Management Responsibilities", "points": ["(a) Find out how and where ladders are being used in your premises.", "(b) Check whether a safer system of work can be provided.", "(c) Provide means whereby portable ladders can be secured at the top.", "(d) If this is impracticable, provide means for securing them at the base.", "(e) Institute a system of periodical inspection, dependent on use, and keep records of purchase, repair, and inspection."]}, {"heading": "Employee Responsibilities", "points": ["(a) Use only issued equipment.", "(b) Check the equipment is in a good condition and being used safely by using the pre-use checklist.", "(c) See that the ladder is firmly secured at the top.", "(d) If this is impracticable, see that it is firmly secured at the base.", "(e) Set the ladder at the correct angle - 1 out to every 4 up.", "(f) Stand the ladder on a firm level base and not on loose material.", "(g) Make sure footwear is in good condition.", "(h) Clean wet, icy, or greasy rungs before use.", "(i) Clean off mud or grease from boots before climbing."]}]}, {"title": "3. When is a ladder the most suitable equipment?", "callout": "Short duration is not the deciding factor in establishing whether use of a ladder is acceptable - you must have first considered risk. As a guide, if your task would require staying up a leaning ladder or stepladder for more than 30 minutes at a time, it is recommended you use alternative equipment.", "points": ["The law says that ladders can be used for work at height when an assessment of the risk for carrying out a task has shown that using equipment offering a higher level of fall protection is not justified because of the low risk and short duration of use, or there are existing workplace features which cannot be altered.", "You should only use ladders in situations where they can be used safely, e.g. where the ladder will be level and stable, and can be secured (where it is reasonably practicable to do so)."]}, {"title": "4. Check the ladder before you use it", "subtitle": "Employees using ladders must be competent in recognising defects and any remedial work. Before starting a task, you should have access to user instructions from the manufacturer. You should always carry out a pre-use check to spot any obvious visual defects.", "points": ["Pre-use check timing: carried out by the user, at the beginning of the working day, and after something has changed (e.g. dropped or moved from dirty to clean area).", "The Stiles: make sure they are not bent or damaged, as the ladder could buckle or collapse.", "The Feet: if missing, worn or damaged the ladder could slip. Check ladder feet when moving from soft/dirty ground to smooth solid surfaces to ensure feet make contact with ground.", "The Rungs: if bent, worn, missing or loose, the ladder could fail.", "The Locking Mechanism: does the mechanism work properly? Ensure any locking bars are fully engaged.", "The Stepladder Platform: if it is split or buckled, the ladder could become unstable or collapse.", "The Steps or Treads: if contaminated, they could be slippery; if fixings are loose, they could collapse.", "Defect reporting: If you spot any of the above defects, DO NOT use the ladder and notify your employer/manager."]}, {"title": "5. Using your step ladder safely", "points": ["Check all four stepladder feet are in contact with the ground and the steps are level.", "Only carry light materials and tools.", "Don''t overreach.", "Don''t stand and work on the top three steps (including a step forming the very top of the stepladder) unless there is a suitable handhold.", "Ensure any locking devices are engaged.", "Try to position the stepladder to face the work activity and not side on.", "Try to avoid work that imposes a side loading, such as side-on drilling through solid materials (e.g. bricks or concrete).", "Where side loadings cannot be avoided, prevent steps from tipping over (e.g. by tying the steps). Otherwise use a more suitable access equipment.", "Maintain three points of contact at the working position (two feet and one hand, or two feet and body supported by stepladder)."]}, {"title": "6. What about the place of work where ladder will be used?", "points": ["On firm ground.", "On level ground - refer to manufacturer''s pictograms. Use proprietary levelling devices, NOT ad-hoc packing such as bricks, blocks, or timbers.", "On clean, solid surfaces (no oil, moss, or leaf litter) and free of loose material (sand, packaging materials).", "Where it will not be struck by vehicles (protect the area using suitable barriers or cones).", "Where it will not be pushed over by other hazards such as doors or windows (secure doors and windows where possible - never block fire exits).", "Where the general public are prevented from using it, walking underneath it, or being at risk (barriers, cones, or guard at base)."]}, {"title": "7. What about the condition of the equipment?", "points": ["Have no visible defects. Carry out a pre-use check each working day.", "Have an up-to-date record of detailed visual inspections carried out regularly by a competent person in accordance with manufacturer instructions.", "Ladders that are part of a scaffold system must be inspected every seven days.", "Be suitable for intended use, strong and robust enough for the job.", "When doing an inspection, look for: damaged or worn feet, twisted/bent/dented stiles, cracked/worn/bent/loose rungs, missing or damaged tie rods, cracked or damaged welded joints, loose rivets, or damaged stays."]}]}', 'When should you carry out a Pre-use check on a ladder?', '["Only after an accident or near-miss occurs on site", "By the user at the start of each working day, and after any change or drop", "Once a week by the main contractor safety officer", "Only if the ladder appears visibly buckled or broken"]', 1, 1);
INSERT OR REPLACE INTO tbts (id, doc_code, title, doc_owner, last_revision, next_revision, category, prepare_text, reason_text, why_text, outline_text, content_json, comprehension_question, comprehension_options_json, correct_option_index, active) VALUES ('AVC011', 'AVC011', 'Personal Protective Equipment (PPE)', 'Operations Director', '01/02/2026', '01/02/2028', 'General Safety', 'Quiet location? PPE samples ready? Correct gear displayed?', 'To ensure all operatives understand mandatory site PPE standards and correct maintenance of life-saving gear.', 'PPE is the last line of defense against workplace injury and fatal hazards.', 'Covers site mandatory PPE, head, eye, hand, foot, and respiratory protection standards.', '{"prepare": "Quiet location? PPE samples ready? Correct gear displayed?", "reason": "To ensure all operatives understand mandatory site PPE standards and correct maintenance of life-saving gear.", "why": "PPE is the last line of defense against workplace injury and fatal hazards.", "outline": "Covers site mandatory PPE, head, eye, hand, foot, and respiratory protection standards.", "sections": [{"title": "1. Site Mandatory PPE Rules", "body": "On Three Eagles Ltd and AGC sites, 5-point mandatory PPE is enforced at all times: Safety Helmet (EN 397 with chinstrap where working at height), Hi-Vis Vest/Jacket (EN ISO 20471 Class 2/3), Safety Footwear (EN ISO 20345 S3 with steel/composite toecap and midsole penetration protection), Protective Gloves (EN 388 matched to the hazard), and Eye Protection (EN 166)."}, {"title": "2. Hierarchy of Hazard Control", "body": "PPE does not remove hazards; it only provides a barrier between the worker and the hazard. Employers must always prioritize Elimination, Substitution, Engineering Controls (e.g. LEV dust extraction), and Administrative Controls before relying solely on PPE."}, {"title": "3. Inspection, Care, and Replacement", "points": ["Check hard hats daily for cracks, UV degradation, or impacts. Replace any helmet that has taken a severe strike or is older than manufacturer shelf life.", "Never store hard hats on the rear dashboard of vans where sun degrades the polymer.", "Replace gloves when torn, worn thin, or saturated with chemical/oil.", "Ensure safety boots have intact tread and are fully laced to prevent ankle roll.", "Report lost, defective, or ill-fitting PPE immediately to your supervisor for free replacement."]}]}', 'Why is Personal Protective Equipment (PPE) considered the last line of defense?', '["Because it is the most expensive way to eliminate site hazards", "Because hazards should first be eliminated, substituted, or controlled by engineering before relying on PPE", "Because operatives only need to wear it during HSE inspections", "Because PPE completely prevents 100% of accidents without any risk"]', 1, 1);
INSERT OR REPLACE INTO tbts (id, doc_code, title, doc_owner, last_revision, next_revision, category, prepare_text, reason_text, why_text, outline_text, content_json, comprehension_question, comprehension_options_json, correct_option_index, active) VALUES ('AVC022', 'AVC022', 'Dust Kills - Control of Dust Hazards', 'Operations Director', '15/01/2026', '14/01/2028', 'Occupational Health', 'Quiet location? M-Class vacuum and FFP3 mask example ready?', 'To raise awareness of Respirable Crystalline Silica (RCS) and wood dust causing chronic lung disease and silicosis.', 'Over 500 UK construction workers die every year from silica dust exposure.', 'Covers dust suppression, on-tool extraction (M-Class/H-Class), and face-fit tested FFP3 masks.', '{"prepare": "Quiet location? M-Class vacuum and FFP3 mask example ready?", "reason": "To raise awareness of Respirable Crystalline Silica (RCS) and wood dust causing chronic lung disease and silicosis.", "why": "Over 500 UK construction workers die every year from silica dust exposure.", "outline": "Covers dust suppression, on-tool extraction (M-Class/H-Class), and face-fit tested FFP3 masks.", "sections": [{"title": "1. The Danger of Respirable Crystalline Silica (RCS)", "body": "Silica dust is 100 times smaller than a grain of sand. When inhaled into the deep lung, it causes irreversible scarring (silicosis), chronic obstructive pulmonary disease (COPD), and lung cancer. Symptoms often take 10-20 years to appear."}, {"title": "2. High Risk Activities", "points": ["Chasing, cutting, grinding, or scabbling concrete, blockwork, stone, and mortar.", "Drilling holes in concrete ceilings and masonry.", "Dry sweeping indoors (STRICTLY PROHIBITED - use M-Class vacuum or wet damp sweeping).", "Sanding drywall plaster joint compound without vacuum sander."]}, {"title": "3. Required Control Measures", "points": ["On-tool local exhaust ventilation (LEV): Always use certified M-Class or H-Class extractors connected directly to the power tool shroud.", "Water suppression: Use pressurized water bottles when cutting masonry externally.", "Respiratory Protective Equipment (RPE): FFP3 disposable mask or half-mask. Must be face-fit tested to your facial shape, and you MUST be clean-shaven."]}]}', 'What minimum class of on-tool vacuum extraction is legally required for construction silica dust?', '["Standard domestic L-Class hoover", "M-Class or H-Class extraction unit with HEPA filtration", "No extraction needed if windows are open", "Dry broom sweeping only"]', 1, 1);
INSERT OR REPLACE INTO tbts (id, doc_code, title, doc_owner, last_revision, next_revision, category, prepare_text, reason_text, why_text, outline_text, content_json, comprehension_question, comprehension_options_json, correct_option_index, active) VALUES ('AVC024', 'AVC024', 'Housekeeping & Site Waste Management', 'Operations Director', '10/02/2026', '09/02/2028', 'Site Logistics', 'Quiet location? Good lighting? Site photos ready?', 'To eliminate slips, trips, falls, and fire hazards caused by poor housekeeping.', 'Over 30% of construction injuries are caused by slips, trips, and messy walkways.', 'Covers clean-as-you-go policy, trailing cables, access corridors, and waste segregation.', '{"prepare": "Quiet location? Good lighting? Site photos ready?", "reason": "To eliminate slips, trips, falls, and fire hazards caused by poor housekeeping.", "why": "Over 30% of construction injuries are caused by slips, trips, and messy walkways.", "outline": "Covers clean-as-you-go policy, trailing cables, access corridors, and waste segregation.", "sections": [{"title": "1. Clean As You Go Policy", "body": "Every operative is responsible for keeping their immediate work area clean, tidy, and clear of tripping hazards. Do not wait for the end of the week. Clear packaging, timber offcuts, cable ties, and masonry rubble continuously."}, {"title": "2. Clear Escape Routes and Corridors", "points": ["All emergency fire exit routes, corridors, and stairwells must remain 100% unobstructed at all times.", "Do NOT store pallets, tools, or building materials in hallways, fire door vestibules, or lift lobbies.", "Elevate trailing cables off the floor using cable hooks, stands, or overhead supports to prevent trip hazards."]}, {"title": "3. Waste Segregation & Environmental Care", "points": ["Separate materials into designated skips / bins: Wood, Gypsum/Plasterboard, Metal, General Waste, and Hazardous.", "Keep flammable liquids (paints, solvents, adhesives) in bunded metal COSHH cabinets when not in use.", "Report any overflowing skips or uncollected debris to site management immediately."]}]}', 'Under the site Clean-As-You-Go policy, when should waste and scrap materials be cleared?', '["Only at the end of the month", "Continuously throughout the shift and immediately upon task completion", "Leave it for the night cleaner shift to sort out", "Only when the floor area becomes completely blocked"]', 1, 1);
